I think that {infer} could benefit from applying more [tidyverse styling](http://style.tidyverse.org/syntax.html) for code syntax. To show cumulative change, I've made up some {infer} inspired code examples (with no particular logic, just to show a difference).

<details>
<summary>Raw example</summary>

```r
hypothesize <- function(x, null, ...) {
  
  hypothesize_checks(x, null)
  
  if( (null == "point") && (length(dots) == 0) ){
    stop_glue("Provide a parameter and a value to check such as `mu = 30` ",
              "for the point hypothesis.")
  }
  
  if(null == "independence" && length(dots) > 0) {
    warning_glue("Parameter values are not specified when testing that two ",
                 "variables are independent.")
  }
  
  if(!is.null(null) && null == "independence")
    attr(x, "type") <- "permute"
  
  return(tibble::as_tibble(x))
}

calc_impl.t <- function(stat, x, order, ...) {
  
  if (attr(x, "theory_type") == "Two sample t") {
    df_out <- x %>%
      dplyr::summarize(stat = stats::t.test(
        !!attr(x, "response") ~ !!attr(x, "explanatory"), ...
      )[["statistic"]])
  }
  # For hypothesis testing
  else {
    x %>%
      dplyr::summarize(stat = stats::t.test(
        !!attr(x, "response"), 
        mu = attr(x, "params"),
        ...)[["statistic"]])
  }
}

calculate <- function(x,
                      stat = c(
                        "mean",
                        "median",
                        "sd",
                        "prop",
                        "diff in means",
                        "diff in medians",
                        "diff in props",
                        "Chisq",
                        "F",
                        "slope",
                        "correlation",
                        "t",
                        "z"
                      ),
                      order = NULL,
                      ...) {
  if (is.null(attr(x, "generate")) || !attr(x, "generate")) {
    if (is.null(attr(x, "null"))) {
      x$replicate <- 1L
    }
    else if (stat %in% c(
      "mean",
      "median",
      "sd",
      "prop",
      "diff in means",
      "diff in medians",
      "diff in props",
      "slope",
      "correlation"
    ))
      stop_glue(
        "Theoretical distributions do not exist (or have not been ",
        "implemented) for `stat` = \"{stat}\". Are you missing ",
        "a `generate()` step?"
      )
  }
}
```
